ALTER TABLE public.ride_requests ADD COLUMN regional_time_events jsonb;
ALTER TABLE public.trips ADD COLUMN regional_time_events jsonb;
CREATE FUNCTION public.validate_regional_time_events() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE e jsonb; result jsonb := '[]'; instant timestamptz; prior timestamptz; BEGIN IF NEW.regional_time_events IS NULL THEN RETURN NEW; END IF; IF jsonb_typeof(NEW.regional_time_events)<>'array' OR jsonb_array_length(NEW.regional_time_events)>20 THEN RAISE EXCEPTION 'Invalid regional time events'; END IF; FOR e IN SELECT value FROM jsonb_array_elements(NEW.regional_time_events) LOOP BEGIN instant:=public.pilot_local_instant((e->>'date')::date,nullif(e->>'time','')::time,e->>'timezone'); EXCEPTION WHEN OTHERS THEN instant:=NULL; END; IF instant IS NOT NULL AND prior IS NOT NULL AND instant<prior THEN RAISE EXCEPTION 'Requested local times are out of order'; END IF; result:=result||jsonb_build_array(jsonb_build_object('kind',e->>'kind','date',e->>'date','time',e->>'time','timezone',e->>'timezone','source','user_selected','utc',instant,'status',CASE WHEN instant IS NULL THEN 'review_required' ELSE 'resolved' END)); IF instant IS NOT NULL THEN prior:=instant; END IF; END LOOP; NEW.regional_time_events:=result; RETURN NEW; END $$;
CREATE TRIGGER validate_regional_request_times BEFORE INSERT OR UPDATE OF regional_time_events ON public.ride_requests FOR EACH ROW EXECUTE FUNCTION public.validate_regional_time_events();
CREATE FUNCTION public.copy_regional_time_events() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NEW.ride_request_id IS NOT NULL THEN SELECT regional_time_events INTO NEW.regional_time_events FROM public.ride_requests WHERE id=NEW.ride_request_id; END IF; RETURN NEW; END $$;
CREATE TRIGGER copy_regional_trip_times BEFORE INSERT ON public.trips FOR EACH ROW EXECUTE FUNCTION public.copy_regional_time_events();
CREATE TRIGGER validate_regional_trip_times BEFORE INSERT OR UPDATE OF regional_time_events ON public.trips FOR EACH ROW EXECUTE FUNCTION public.validate_regional_time_events();
COMMENT ON COLUMN public.ride_requests.regional_time_events IS 'Entered local event values and server-validated UTC instants; NULL legacy values require review. No historical backfill.';
COMMENT ON COLUMN public.trips.regional_time_events IS 'Copied request local events or revalidated explicit edits; does not enable automatic assignment.';